export const getExportAdminChatbotEvaluationUrl = (id: number,
    params?: ExportAdminChatbotEvaluationParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/admin/chatbot/evaluations/${id}/export?${stringifiedParams}` : `/api/admin/chatbot/evaluations/${id}/export`
}

